<section id="departure-periods"><h2>ช่วงเดินทางและราคาแพ็คเกจส่วนตัว</h2><p>แต่ละการจองเป็นกรุ๊ปส่วนตัว เลือกวันไป–กลับภายในช่วงที่เปิดขาย ราคาต่อคนขึ้นกับระดับบริการและจำนวนผู้เดินทาง</p>
<?php foreach ($available as $dep): ?><div class="panel"><h3><?= thai_date($dep['start_date']) ?> – <?= thai_date($dep['end_date']) ?></h3><p>จองล่วงหน้าอย่างน้อย <?= (int)$dep['lead_days'] ?> วัน · <?= (int)$tour['days'] ?> วัน <?= (int)$tour['nights'] ?> คืน</p>
<div class="table-scroll"><table class="departure-table"><thead><tr><th>ระดับบริการ</th><th>จำนวนคน / กรุ๊ป</th><th>ราคาต่อคน</th></tr></thead><tbody><?php foreach (json_decode($dep['private_rates'],true) ?: [] as $rate): ?><tr><td><?= e($rate['level']) ?><small class="preline"><?= e($rate['details']) ?></small></td><td><?= (int)$rate['min'] ?>–<?= (int)$rate['max'] ?> คน</td><td>฿<?= money($rate['price']) ?></td></tr><?php endforeach ?></tbody></table></div>
<?php $blocked=json_decode($dep['blackout_dates'] ?? '[]',true) ?: []; if ($blocked): ?><p class="fineprint">วันงดเดินทาง: <?= e(implode(', ',array_map('thai_date',$blocked))) ?></p><?php endif ?></div><?php endforeach ?>
<?php if (!$available): ?><p class="notice">ยังไม่มีช่วงเดินทางที่เปิดรับคำขอ</p><?php endif ?></section>
